import * as THREE from 'three/webgpu';
import { texture, uv, vec4, float, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const width = 1.6;
  const height = 1.0;

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const imageUrl = config?.assets?.imageUrl || '/prism-mock/home/nodes/cta-hero-isolated.png';
  const map = ctx.textureLoader(imageUrl);
  if (map) {
    map.colorSpace = THREE.SRGBColorSpace;
  }

  const grainStrength = uniform(0.035);

  if (map) {
    const texNode = texture(map, uv());
    // subtle grain via pseudo-random noise based on uv
    const uvCoord = uv();
    const noise = float(uvCoord.x).mul(12.9898).add(float(uvCoord.y).mul(78.233)).sin().mul(43758.5453).fract();
    const grain = noise.sub(0.5).mul(grainStrength);
    const finalColor = texNode.rgb.add(grain).clamp(0.0, 1.0);
    material.colorNode = vec4(finalColor, texNode.a);
  } else {
    // fallback engineered gradient using ink/surface tones if texture missing
    const uvCoord = uv();
    const inkColor = vec4(0.086, 0.086, 0.114, 1.0);
    const surfaceColor = vec4(0.043, 0.043, 0.063, 1.0);
    const gradient = inkColor.mix(surfaceColor, uvCoord.y);
    material.colorNode = gradient;
  }

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'hub-collection-card-1';

  const pos = config?.scenePosition?.position || [-3.2, -0.3, 0];
  const rot = config?.scenePosition?.rotation || [0, 0, 0];
  const scl = config?.scenePosition?.scale || [1, 1, 1];

  mesh.position.set(pos[0], pos[1], pos[2]);
  mesh.rotation.set(rot[0], rot[1], rot[2]);
  mesh.scale.set(scl[0], scl[1], scl[2]);

  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && typeof map.dispose === 'function') {
      map.dispose();
    }
  };

  return mesh;
}
